package com.example.customers.domain;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * The filters applied to customer page and count queries.
 *
 * @param name     name terms entered by the user
 * @param statuses accepted statuses; empty means every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
    private static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    public CustomerFilter {
        String strippedName = name == null ? "" : name.strip();
        name = strippedName.isEmpty() ? "" : WHITESPACE.matcher(strippedName).replaceAll(" ");
        statuses = statuses == null || statuses.isEmpty()
                ? Set.of()
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    public static CustomerFilter empty() {
        return EMPTY;
    }
}
